<?php
declare(strict_types=1);
require_once __DIR__.'/legacy-migration/LegacyWorkforceReferenceProfiler.php';
function requiredEnv(string$n):string{$v=getenv($n);if($v===false||$v==='')throw new RuntimeException("Missing {$n}");return$v;}
$at=$argv[1]??null;if(!is_string($at))throw new InvalidArgumentException('Usage: php profile-legacy-workforce-references.php <RFC3339-profiled-at>');$prefix=requiredEnv('FMONITOR_TABLE_PREFIX');if(preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1)throw new InvalidArgumentException('Invalid local table prefix');
$local=new mysqli(getenv('FMONITOR_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_DB_USER')?:'fmonitor2_demo',getenv('FMONITOR_DB_PASSWORD')?:'fmonitor2_demo_local',getenv('FMONITOR_DB_NAME')?:'fmonitor2_demo',(int)(getenv('FMONITOR_DB_PORT')?:23306));$local->set_charset('utf8mb4');$source=new mysqli(getenv('FMONITOR_SOURCE_HOST')?:'127.0.0.1',requiredEnv('FMONITOR_SOURCE_USER'),requiredEnv('FMONITOR_SOURCE_PASSWORD'),getenv('FMONITOR_SOURCE_NAME')?:'c1_fmonitor',(int)(getenv('FMONITOR_SOURCE_PORT')?:13306));$source->set_charset('utf8mb4');
$local->query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$local->query('START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY');$source->query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$source->query('START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY');try{$catalog=[];foreach($local->query("SELECT installer_tab_id FROM `{$prefix}fm2_workforce_catalog`")->fetch_all(MYSQLI_ASSOC)as$r)$catalog[ltrim((string)$r['installer_tab_id'],'0')]=true;$facts=[];$seenObjects=[];foreach($local->query("SELECT legacy_object_id,content_sha256,payload_json FROM `{$prefix}fm2_history_source_snapshots` ORDER BY legacy_object_id,id DESC")->fetch_all(MYSQLI_ASSOC)as$s){$object=(int)$s['legacy_object_id'];if(isset($seenObjects[$object]))continue;$seenObjects[$object]=true;$json=(string)$s['payload_json'];if(!hash_equals((string)$s['content_sha256'],hash('sha256',$json)))continue;$payload=json_decode($json,true,flags:JSON_THROW_ON_ERROR);foreach($payload['attributions']??[]as$a){$raw=trim((string)($a['tab_id']??''));$canonical=ltrim($raw,'0');if($canonical!==''&&!isset($catalog[$canonical]))$facts[]=['tab_id'=>$raw,'fio'=>$a['fio']??null,'ctime'=>$a['ctime']??null];}}$installers=$source->query("SELECT tab_id,tab_id_char,lastname,name,s_name FROM fm_installators WHERE tab_id<>999999")->fetch_all(MYSQLI_ASSOC);$users=$source->query('SELECT name FROM users')->fetch_all(MYSQLI_ASSOC);$result=LegacyWorkforceReferenceProfiler::profile($facts,$installers,$users,$at,requiredEnv('FMONITOR_PROFILE_HASH_KEY'));$source->commit();$local->commit();echo json_encode($result,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";}catch(Throwable$e){$source->rollback();$local->rollback();throw$e;}finally{$source->close();$local->close();}
